import sys, random, itertools
sys.path.insert(0, 'src')
from seq import dedupe


def ref(items):
    out = []
    for x in items:
        if not any(x == y for y in out):
            out.append(x)
    return out


pool = [1, 2, 1.0, 'a', '1', True, None, 3.5, [1], [2], [1.0], (1,), {'a': 1},
        {1, 2}, frozenset({1, 2}), b'ab', bytearray(b'ab'), [], {}, (1, 2)]

random.seed(1)
bad = []
for n in range(1, 5):
    for _ in range(100000):
        c = [random.choice(pool) for _ in range(n)]
        try:
            r = ref(c)
        except Exception as e:
            continue
        try:
            g = dedupe(c)
        except Exception as e:
            bad.append((c, 'EXC ' + repr(e), None))
            continue
        if r != g or [repr(v) for v in r] != [repr(v) for v in g]:
            bad.append((c, r, g))
print('mismatches:', len(bad))
seen_repr = set()
for c, r, g in bad:
    k = (repr(c), repr(r), repr(g))
    if k in seen_repr:
        continue
    seen_repr.add(k)
    print(c, '  ref=', r, '  got=', g)
    if len(seen_repr) > 15:
        break

